def solve(g):
    h,w=len(g),len(g[0])
    # collect residue->color constraints for candidate periods
    for p in range(1,31):
        m={}
        ok=True
        for i in range(h):
            for j in range(w):
                c=g[i][j]
                if c:
                    r=(j-i)%p
                    if r in m and m[r]!=c: ok=False; break
                    m[r]=c
            if not ok: break
        if ok and len(m)==p:  # minimal period, fully covered
            return [[m[(j-i)%p] for j in range(w)] for i in range(h)]

